#pragma once
#include "resource_transfer131.hpp"
#include "resource_transfer_network_profile131.hpp"
#include "quick_drop_network131.hpp"
#include <array>
namespace wht {
inline bool ResourceTransferNetworkCode131(uintptr_t base,unsigned build){for(const auto& p:transferNetworkProfiles131)if(p.build==build)return ResourceTextGuard131(base,p);return false;}
inline std::array<unsigned char,10> ResourceTransferPacket131(const ResourceTransferRequest131& r){std::array<unsigned char,10> bytes{{0x51,static_cast<unsigned char>(r.slot)}};for(unsigned i=0;i<4;++i){bytes[2+i]=static_cast<unsigned char>(uint32_t(r.amounts[0])>>(i*8));bytes[6+i]=static_cast<unsigned char>(uint32_t(r.amounts[1])>>(i*8));}return bytes;}
inline bool TransferAllied131(uintptr_t base,unsigned build,const ResourceTransferSource131& v){const auto* p=ResourceProfileFor131(build);if(!p||v.target.physical>=24)return false;__try{const auto ally=*reinterpret_cast<uintptr_t*>(v.source.player+p->allianceOffset);if(!ResourceIdentity131(ally,base,p->allianceTable))return false;return (uint32_t(reinterpret_cast<int(__thiscall*)(uintptr_t)>(base+p->integerFn)(ally+p->allianceMask))&(1u<<v.target.physical))!=0;}__except(1){return false;}}
template<class Session,class Read,class Allied,class Send> bool ResourceTransferNetworkFlow131(const ResourceTransferRequest131& r,Session session,Read read,Allied allied,Send send,std::string& report){if(r.slot>=24||r.amounts[0]<0||r.amounts[1]<0||(!r.amounts[0]&&!r.amounts[1])){report="Transfer: invalid request";return false;}const auto active=session();ResourceTransferSource131 before,now;if(!active||!read(r.slot,before)||!read(r.slot,now)||!ResourceTransferBalances131(before,now)||now.target.physical!=r.slot||!allied(now)){report="Transfer: active allied player and stable game session required";return false;}for(unsigned i=0;i<2;++i)if(now.source.values[i]<r.amounts[i]||now.target.values[i]<0||static_cast<int64_t>(now.target.values[i])+r.amounts[i]>9999999){report="Transfer: insufficient balance or native resource limit";return false;}ResourceTransferSource131 check;if(session()!=active||!read(r.slot,check)||!ResourceTransferBalances131(now,check)||!allied(check)||session()!=active){report="Transfer: player or session changed before submission";return false;}const auto bytes=ResourceTransferPacket131(r);if(!send(bytes)){report="Transfer: native action submission failed; do not automatically retry";return false;}report="Transfer queued: Gold "+std::to_string(r.amounts[0])+", Lumber "+std::to_string(r.amounts[1])+" to Player "+std::to_string(r.slot+1)+" (awaiting game processing)";return true;}
inline bool SubmitResourceTransfer131(const DropNetworkApi131& api,const std::array<unsigned char,10>& bytes){if(!api)return false;__try{DropBuffer131 buffer{api.table,bytes.data(),0,0,10,10};api.send(&buffer,0);return true;}__except(1){return false;}}
inline bool ResourceTransferNetworkCommand131(uintptr_t base,unsigned build,const std::wstring& name,const std::wstring& args,std::string& report){ResourceTransferRequest131 request;if(!ParseResourceTransfer131(name,args,request)){report="Usage: #gg/#gl player(1..24) amount; #ggl player(1..24) gold lumber; #gll player(1..24) lumber gold";return false;}const auto* p=InventoryProfile(build);const auto* np=DropNetworkProfileFor131(build);if(!p||!np||!ResourceTransferNetworkCode131(base,build)){report="Transfer: native action profile mismatch";return false;}const auto api=DropNetworkNative131(base,*np,*p);return ResourceTransferNetworkFlow131(request,[&](){return DropSession131(api);},[&](unsigned slot,ResourceTransferSource131& out){return ReadResourceTransfer131(base,build,slot,out);},[&](const ResourceTransferSource131& v){return TransferAllied131(base,build,v);},[&](const std::array<unsigned char,10>& bytes){return SubmitResourceTransfer131(api,bytes);},report);}
}
